import requests

response = requests.post(
    "https://api.deepseek.com/v1/chat/completions",
    json={
        "model": "deepseek-v4-flash",
        "messages": [{"role": "user", "content": "讲个故事"}],
        "temperature": 0.7,  # 可调整
        "top_p": 0.9        # 可调整
    }
)

